 s=series or bullish_series();n=sum(c.is_complete for c in s.candles);data=dict(timeframe_evidence_id="e-"+s.series_id,created_at=BASE_TIME,underlying_symbol=s.underlying_symbol,exchange=s.exchange,timeframe=s.timeframe,candle_series_id=s.series_id,quality_result_id="q-"+s.series_id,quality_status=status,candle_count=len(s.candles),complete_candle_count=n,incomplete_candle_count=len(s.candles)-n,first_candle_start_at=s.candles[0].start_at,latest_candle_start_at=s.candles[-1].start_at,latest_candle_end_at=s.candles[-1].end_at,latest_complete_candle_end_at=s.candles[n-1].end_at if n else None,age_seconds=0.,freshness_threshold_seconds=999.,minimum_required_candles=1,history_sufficient=history_sufficient,latest_candle_complete=latest_candle_complete,blockers=blockers or (("quality_"+status.lower(),) if status not in {"READY","READY_WITH_WARNINGS"} else ()),warnings=warnings);data.update(changes);return TimeframeEvidenceV1(**data)
